# the helper clauses (one per line, no final full stop): swipl loads them as a file, the kernel asserts each through term_to_atom/2.
# `tw_main/1` prints the first error's formal as `<ex:Name,FirstArg>` (a stream blob in an argument is not repeatable), else `<failed>`.
const _TW_PRELUDE = [
    # PRELUDE-BEGIN
    raw"tw_gc :- get_code(user_input, X), format(user_output, '<~d>~n', [X])",
    raw"tw_gcs(N) :- ( N > 0 -> tw_gc, N1 is N-1, tw_gcs(N1) ; true )",
    raw"tw_skip(N) :- ( N > 0 -> get_code(user_input, _), N1 is N-1, tw_skip(N1) ; true )",
    raw"tw_wrap(F, In) :- open(F, read, In, [bom(false)]), set_prolog_IO(In, user_output, user_error)",
    raw"tw_props :- stream_property(user_output, buffer(B1)), stream_property(user_error, buffer(B2)), format(user_output, '<buf:~w,~w>~n', [B1, B2])",
    raw"tw_lc :- line_count(user_input, A), line_count(user_output, B), line_count(user_error, C), format(user_output, '<lc:~w,~w,~w>~n', [A, B, C])",
    raw"tw_main(G) :- ( catch(G, error(F, _), ( ( F =.. [N, A|_] -> format(user_output, '<ex:~w,~w>~n', [N, A]) ; format(user_output, '<ex:~w>~n', [F]) ), fail )) -> true ; format(user_output, '<failed>~n', []) )"
    # PRELUDE-END
]

