"The content of the input file a case names (the generator's `decode_file`): `\\n`, `\\^D`, `gen:L,W`."
function _tw_file(spec::String)::String
    m = match(r"^gen:(\d+),(\d+)$", spec)
    m === nothing || return repeat("x"^(parse(Int, m[2]) - 1) * "\n", parse(Int, m[1]))
    return replace(spec, "\\n" => "\n", "\\^D" => "\x04")
end

"A text as the pins hold it (the generator's `enc`): a backslash doubled, a newline `\\n`. ONE encoder for both sides."
_tw_enc(s::AbstractString)::String = replace(replace(s, "\\" => "\\\\"), "\n" => "\\n")

"The pin of case `id`: swipl's encoded output."
function _tw_pin(id::String)::Union{Nothing, String}
    for l in _TW_PINNED
        k, v = split(l, " "; limit=2)
        k == id && return _tw_enc(String(v))     # the literal is the TEXT swipl wrote; the kernel side is encoded the same way
    end
    return nothing
end

const _TW_GOT = Dict{String, String}()      # case id -> the kernel's encoding, filled by the pinned rows

"""
A booted database whose three user streams are buffers, with the prelude loaded and the two runners `tw_load/1` and `tw_run/1` defined:
`(db, (ui, uo, ue), (inb, outb, errb))`.
"""
function _tw_db()
    db = _RDB()
    ld = db.ld
    bufs = (IOBuffer(), IOBuffer(), IOBuffer())
    ui = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, bufs[1])
    uo = LK.set_standard_stream!(ld, LK.SNO_USER_OUTPUT, bufs[2])
    ue = LK.set_standard_stream!(ld, LK.SNO_USER_ERROR, bufs[3])
    _radd!(
        db,
        _rf("tw_load", _rv(1)),
        _rconj(_rf("term_to_atom", _rv(2), _rv(1)), _rf("assertz", _rv(2)))
    )
    _radd!(
        db,
        _rf("tw_run", _rv(1)),
        _rconj(_rf("term_to_atom", _rv(2), _rv(1)), _rf("call", _rv(2)))
    )
    for clause in _TW_PRELUDE
        @test !isempty(_rcall(db, _rf("tw_load", _rs(Symbol(clause)))))
    end
    return db, (ui, uo, ue), bufs
end

"Run the text `goal` as `tw_main((goal))` in `db`: true if the runner answered (it always does: `tw_main/1` catches an error and a failure)."
function _tw_run(db::_RDB, goal::String)::Bool
    return !isempty(_rcall(db, _rf("tw_run", _rs(Symbol("tw_main((" * goal * "))")))))
end

"Flush the user streams and take what `user_output` holds."
function _tw_take(db::_RDB, outb::IOBuffer)::String
    for i in (LK.SNO_USER_OUTPUT, LK.SNO_USER_ERROR)
        s = db.ld.IO_streams[i + 1]
        s === nothing || LK.Sflush(s)
    end
    return String(take!(outb))
end

"The kernel's transcript of a case: the file written, the body run, the contents of the buffer `user_output` is."
function _tw_transcript(fspec::String, body::String)::String
    db, _, (_, outb, _) = _tw_db()
    return mktemp() do path, io
        write(io, _tw_file(fspec))
        close(io)
        @test _tw_run(db, replace(body, "{F}" => path))
        return _tw_take(db, outb)
    end
end

@testset "swipl-pinned rows: the whole output of each case (prompt and events)" begin
    # UNVERIFIED on the kernel: gate decides
    for (id, fspec, body) in _TW_CASES
        @testset "$id" begin
            out = _tw_transcript(fspec, body)
            enc = _tw_enc(out)
            _TW_GOT[id] = enc
            pin = _tw_pin(id)
            @test pin !== nothing
            @test !isempty(out)                              # both sides non-empty (swipl's is checked by the generator)
            pin === nothing || @test enc == pin
        end
    end
end

# the stream of a booted database `db` for the hand-written rows below: an input over `text`, the user output a buffer
function _tw_streams(db::_RDB, text::String)
    ld = db.ld
    inb, outb = IOBuffer(text), IOBuffer()
    ui = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, inb)
    uo = LK.set_standard_stream!(ld, LK.SNO_USER_OUTPUT, outb)
    return ui, uo, outb
end

@testset "the registry of local data: first free entry, free, reuse (src/os/pl-stream.jl registerLocalData!; ORIGINAL, DIVERGES owner TH1)" begin
    # UNVERIFIED on the kernel: gate decides
    gd = LK.setupProlog(_R)
    ld1 = LK.PL_local_data{_R}(gd)
    ld2 = LK.PL_local_data{_R}(gd)
    tbl = gd.ld_table
    @test isempty(tbl)
    i1 = LK.registerLocalData!(tbl, ld1)
    i2 = LK.registerLocalData!(tbl, ld2)
    @test (i1, i2) == (1, 2)
    @test tbl[1] === ld1 && tbl[2] === ld2
    LK.unregisterLocalData!(tbl, 1)
    @test tbl[1] === nothing && length(tbl) == 2                  # the slot stays, empty
    @test LK.registerLocalData!(tbl, ld2) == 1                    # the FIRST free entry is reused, no new one
    @test length(tbl) == 2 && tbl[1] === ld2
    LK.unregisterLocalData!(tbl, 0)                               # out of range: nothing
    LK.unregisterLocalData!(tbl, 9)
    @test length(tbl) == 2 && tbl[1] === ld2 && tbl[2] === ld2
    LK.unregisterLocalData!(tbl, 2)
    @test count(isnothing, tbl) == 1
    @test LK.registerLocalData!(tbl, ld1) == 2                    # entry 1 is taken, 2 is the free one
end

@testset "wrapIO: the record, the cleared flag, the registered engine, the guard on ld.GD (pl-file.c:6047-6068; DIVERGES 2-4 of the wrappedIO header)" begin
    # UNVERIFIED on the kernel: gate decides
    gd = LK.PL_global_data{_R}()
    ld = LK.PL_local_data{_R}(gd)
    ld.GD = gd                                                    # initIO (inside set_standard_stream!) reads the database of the engine
    s = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, IOBuffer("ab\n"))
    ld.GD = nothing                                               # the guard under test: wrapIO records the database when there is none
    s.flags |= LK.SIO_FILE                                        # the flag upstream's wrapIO clears (the kernel's file streams carry none)
    flags0 = s.flags
    @test s.wrapped === nothing
    LK.wrapIO(gd, ld, s, true)
    w = s.wrapped
    @test w isa LK.wrappedIO
    @test w.user_read
    @test w.saved_flags == LK.SIO_FILE                            # exactly the bit that was cleared
    @test (s.flags & LK.SIO_FILE) == 0
    @test s.flags == flags0 & ~LK.WRAP_CLEAR_FLAGS                # nothing else moved
    @test w.table === gd.ld_table
    @test w.ld == 1 && gd.ld_table[1] === ld
    @test ld.GD === gd                                            # recorded because it was nothing
    # an engine that has its database keeps it
    gd2 = LK.PL_global_data{_R}()
    ld2 = LK.PL_local_data{_R}(gd2)
    ld2.GD = gd2
    s2 = LK.set_standard_stream!(ld2, LK.SNO_USER_INPUT, IOBuffer("x"))
    LK.wrapIO(gd, ld2, s2, true)
    @test ld2.GD === gd2
    # a stream without the flag: nothing saved
    s3 = LK.set_standard_stream!(ld2, LK.SNO_USER_ERROR, IOBuffer())
    s3.flags &= ~LK.SIO_FILE                                      # SIO_STDIO carries SIO_FILE (pl-stream.jl:112): take it off
    LK.wrapIO(gd, ld2, s3, false)
    @test s3.wrapped.saved_flags == UInt32(0) && !s3.wrapped.user_read
    @test (s3.flags & LK.SIO_FILE) == 0
end

@testset "wrapIO twice keeps ONE record and ONE registered entry; the flag saved at the first wrap stays (DIVERGES 3 of Writer 6; pl-file.c:6047-6068 chains)" begin
    # UNVERIFIED on the kernel: gate decides
    gd = LK.PL_global_data{_R}()
    ld = LK.PL_local_data{_R}(gd)
    ld2 = LK.PL_local_data{_R}(gd)
    s = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, IOBuffer("ab\n"))
    s.flags |= LK.SIO_FILE
    LK.wrapIO(gd, ld, s, true)
    w1 = s.wrapped
    @test gd.ld_table[w1.ld] === ld
    LK.wrapIO(gd, ld2, s, false)
    @test s.wrapped === w1                                        # one record
    @test count(!isnothing, gd.ld_table) == 1                     # one entry: the old one was freed, the new registered
    @test gd.ld_table[w1.ld] === ld2                              # the second engine is the one the read prompts for
    @test w1.saved_flags == LK.SIO_FILE                           # not re-saved from the already cleared flags
    @test w1.user_read                                            # `|=`: a later non-user wrap does not undo it
    @test (s.flags & LK.SIO_FILE) == 0
end

@testset "closing a wrapped stream: closed once, record gone, flag back, entry freed (pl-file.c:6010-6027 closeWrappedIO, pl-stream.c S__close)" begin
    # UNVERIFIED on the kernel: gate decides
    gd = LK.PL_global_data{_R}()
    ld = LK.PL_local_data{_R}(gd)
    s = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, IOBuffer("ab\n"))
    s.flags |= LK.SIO_FILE
    LK.wrapIO(gd, ld, s, true)
    idx = s.wrapped.ld
    @test gd.ld_table[idx] === ld
    @test LK.Sclose(s) == 0
    @test s.wrapped === nothing
    @test (s.flags & LK.SIO_FILE) != 0                            # the cleared flag is back
    @test gd.ld_table[idx] === nothing                            # the entry is free, the table keeps its length
    @test length(gd.ld_table) == idx
    @test s.magic == LK.SIO_CMAGIC
    @test LK.Sclose(s) == -1                                      # a second close is not a second wrapped close
    # direct: the wrapper's close returns the stream's own close result and restores `saved_flags` ONLY
    s2 = LK.set_standard_stream!(ld, LK.SNO_USER_ERROR, IOBuffer())
    LK.wrapIO(gd, ld, s2, true)
    s2.wrapped.saved_flags = LK.SIO_FILE
    w2 = s2.wrapped
    @test LK.closeWrappedIO(s2, w2) == 0
    @test s2.wrapped === nothing && (s2.flags & LK.SIO_FILE) != 0
end

@testset "Sread_user driven directly: the prompt arm, the flush arm, the raw tty, the re-arm, ^D (pl-file.c:5987-6007)" begin
    # UNVERIFIED on the kernel: gate decides
    function setup(text::String; raw::Bool=false)
        db = _RDB()
        ld = db.ld
        ld.GD = db.gd
        ui, uo, outb = _tw_streams(db, text)
        raw && LK.Sset_ttymode(ui, LK.TTY_RAW)
        LK.wrapIO(db.gd, ld, ui, true)
        ld.prompt_next = true
        return db, ld, ui, uo, outb
    end
    # prompt arm: `prompt.next` and not raw -> the prompt is written (and flushed) before the read; the line ends in a newline: re-armed
    _, ld, ui, uo, outb = setup("ab\n")
    @test LK.Sgetcode(ui) == Int('a')
    @test String(take!(outb)) == "|: "
    @test ld.prompt_next                                          # the read ended in a newline
    # a read that does not end in a newline does not re-arm: the prompt flag was consumed by PL_write_prompt
    _, ld, ui, uo, outb = setup("ab")
    @test LK.Sgetcode(ui) == Int('a')
    @test String(take!(outb)) == "|: "
    @test !ld.prompt_next
    # flush arm (no prompt due): the pending output of user_output is flushed, nothing is prompted
    _, ld, ui, uo, outb = setup("ab")
    ld.prompt_next = false
    LK.Sputcode(Int('x'), uo)                                     # line buffered: no newline, still pending
    @test outb.size == 0                                          # nothing reached the buffer yet
    LK.Sgetcode(ui)
    @test String(take!(outb)) == "x"
    @test !ld.prompt_next
    # raw tty: no prompt although `prompt.next`, the flag stays set, the pending output is flushed
    _, ld, ui, uo, outb = setup("ab"; raw=true)
    LK.Sputcode(Int('y'), uo)
    @test LK.Sgetcode(ui) == Int('a')
    @test String(take!(outb)) == "y"
    @test ld.prompt_next
    # end of file: 0, `prompt.next` set again, the eof and error flags of the USER input stream cleared (Sclearerr(Suser_input)); the stream that
    # is wrapped is NOT user_input here, so the clearing is visible on the other stream
    db = _RDB()
    ld = db.ld
    ld.GD = db.gd
    ui, uo, outb = _tw_streams(db, "")
    src = LK.set_standard_stream!(ld, LK.SNO_USER_ERROR, IOBuffer(""))
    ui.flags |= LK.SIO_FEOF | LK.SIO_FERR
    LK.wrapIO(db.gd, ld, src, true)
    ld.prompt_next = false
    mem = zeros(UInt8, 8)
    @test LK.Sread_user(ld, src, src.wrapped, mem, 1, 8) == 0
    @test ld.prompt_next
    @test (ui.flags & (LK.SIO_FEOF | LK.SIO_FERR)) == 0
    # ^D as the one byte read is end of file; as one of several it is a character; the byte is read from `from`
    for (bytes, want) in ((UInt8[4], 0), (UInt8[4, 10], 2), (UInt8[65, 4], 2))
        db = _RDB()
        ld = db.ld
        ld.GD = db.gd
        ui, uo, outb = _tw_streams(db, "")
        src = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, IOBuffer(bytes))
        LK.wrapIO(db.gd, ld, src, true)
        ld.prompt_next = false
        mem = zeros(UInt8, 10)
        @test LK.Sread_user(ld, src, src.wrapped, mem, 3, 8) == want
        want > 0 && @test mem[3:(2 + want)] == bytes
    end
end

@testset "a freed registry entry reads -1: no engine to prompt for (src/os/pl-file.jl Sread_user ::Nothing; DIVERGES owner TH1)" begin
    # UNVERIFIED on the kernel: gate decides
    db = _RDB()
