    ld.GD = db.gd
    ui, uo, outb = _tw_streams(db, "ab\n")
    LK.wrapIO(db.gd, ld, ui, true)
    ld.prompt_next = true
    LK.unregisterLocalData!(db.gd.ld_table, ui.wrapped.ld)
    @test LK.Sgetcode(ui) == -1
    @test (ui.flags & LK.SIO_FERR) != 0                           # a read error, not end of file
    @test String(take!(outb)) == ""                               # nothing was prompted
end

@testset "set_prolog_IO/3 on the kernel: flags, buffering, the error stream, positions, the prompt (pl-file.c:6093-6167)" begin
    # UNVERIFIED on the kernel: gate decides
    # Out == Error: a separate error stream over Out's flags, WRAP_CLEAR_FLAGS cleared, NBUF; Out line buffered; positions shared with the new input
    db, (ui, uo, ue), (inb, outb, errb) = _tw_db()
    ld = db.ld
    uo.flags |= LK.SIO_FILE | LK.SIO_FBUF                         # a file-like, fully buffered output
    uo.flags &= ~LK.SIO_LBUF
    ld.prompt_next = false
    mktemp() do path, io
        write(io, "ab\n")
        close(io)
        @test _tw_run(
            db,
            "open('$path', read, In, [bom(false)]), set_prolog_IO(In, user_output, user_output)"
        )
    end
    nu, no, ne = LK.Suser_input(ld)::LK.IOSTREAM,
    LK.Suser_output(ld)::LK.IOSTREAM,
    ld.IO_streams[LK.SNO_USER_ERROR + 1]::LK.IOSTREAM
    @test no === uo                                               # Out is taken as it is
    @test ne !== uo && ne !== ue
    @test ne.functions == LK.Sstderrfunctions && ne.handle === uo # a stream that writes to Out
    @test (ne.flags & LK.SIO_FILE) == 0                           # `Out->flags & ~WRAP_CLEAR_FLAGS`
    @test (ne.flags & LK.SIO_NBUF) != 0 && (ne.flags & (LK.SIO_FBUF | LK.SIO_LBUF)) == 0
    @test (uo.flags & LK.SIO_LBUF) != 0 && (uo.flags & (LK.SIO_FBUF | LK.SIO_NBUF)) == 0
    @test nu !== ui && nu.wrapped !== nothing && nu.wrapped.user_read
    @test ld.prompt_next                                          # armed by the wrap
    @test LK.Scurin(ld) === nu && LK.Scurout(ld) === uo           # current input and output follow
    for i in LK.SNO_USER_INPUT:LK.SNO_USER_ERROR
        st = ld.IO_streams[i + 1]::LK.IOSTREAM
        @test st.position === nu.posbuf                           # one position record for the three
        @test (st.flags & LK.SIO_RECORDPOS) != 0
    end
    # a write to the error stream reaches Out at once (Swrite_stderr flushes `org`): Out is line buffered by now and `E` has no newline
    LK.Sputcode(Int('E'), ne)
    @test String(take!(outb)) == "E"
    # closing the error stream does not close Out (S_close of Sstderrfunctions: `close` is NULL)
    # (a fall through to Sclose_string(Out) would put a 0 byte into Out's buffer: its `bufp` moves and the next flush writes it)
    bufp0 = uo.bufp
    @test LK.Sclose(ne) == 0
    @test uo.magic == LK.SIO_MAGIC
    @test uo.bufp == bufp0                                        # Out's buffer untouched by the copy's close
    @test LK.Sflush(uo) == 0 && isempty(take!(outb))              # no 0 byte reaches Out
    # Out != Error: the error stream is taken as it is, NBUF set, its other buffering flags cleared
    db2, (ui2, uo2, ue2), _ = _tw_db()
    ue2.flags |= LK.SIO_FBUF
    ue2.flags &= ~LK.SIO_NBUF
    mktemp() do path, io
        write(io, "ab\n")
        close(io)
        @test _tw_run(
            db2,
            "open('$path', read, In, [bom(false)]), set_prolog_IO(In, user_output, user_error)"
        )
    end
    @test db2.ld.IO_streams[LK.SNO_USER_ERROR + 1] === ue2
    @test (ue2.flags & LK.SIO_NBUF) != 0 && (ue2.flags & (LK.SIO_FBUF | LK.SIO_LBUF)) == 0
    # In == user_input: no wrap, the prompt flag untouched, the positions still shared
    db3, (ui3, uo3, ue3), _ = _tw_db()
    db3.ld.prompt_next = false
    @test _tw_run(db3, "set_prolog_IO(user_input, user_output, user_error)")
    @test LK.Suser_input(db3.ld) === ui3 && ui3.wrapped === nothing
    @test !db3.ld.prompt_next
    @test all(
        i -> db3.ld.IO_streams[i + 1].position === ui3.posbuf,
        LK.SNO_USER_INPUT:LK.SNO_USER_ERROR
    )
    @test isempty(db3.gd.ld_table)
    @test (ui3.flags & LK.SIO_RECORDPOS) != 0                     # the loop starts at user_input: its flag is set although it was not wrapped
    # the wrapped engine is the caller's: the registry holds it
    @test count(!isnothing, db.gd.ld_table) == 1 && db.gd.ld_table[nu.wrapped.ld] === db.ld
end

@testset "Swrite_stderr: the count, a flush of the stream it copies, -1 on no bytes (pl-file.c:6071-6079)" begin
    # UNVERIFIED on the kernel: gate decides
    db = _RDB()
    buf = IOBuffer()
    org = LK.set_standard_stream!(db.ld, LK.SNO_USER_OUTPUT, buf)
    org.flags &= ~LK.SIO_LBUF
    org.flags |= LK.SIO_FBUF                                      # fully buffered: only an explicit flush shows the bytes
    mem = collect(codeunits("xEy"))
    @test LK.Swrite_stderr(org, mem, 2, 1) == 1
    @test String(take!(buf)) == "E"                               # flushed by Swrite_stderr, not by anything else
    @test LK.Swrite_stderr(org, mem, 1, 3) == 3
    @test String(take!(buf)) == "xEy"
    @test LK.Swrite_stderr(org, mem, 1, 0) == -1                  # `rc > 0` is false: -1
    # through a stream of the function set: S_write dispatches on Sstderrfunctions
    err = LK.Snew(org, org.flags & ~LK.WRAP_CLEAR_FLAGS, LK.Sstderrfunctions)
    err.flags |= LK.SIO_NBUF | LK.SIO_OUTPUT
    err.flags &= ~(LK.SIO_FBUF | LK.SIO_LBUF)
    LK.Sputcode(Int('z'), err)
    @test String(take!(buf)) == "z"
end

@testset "the template copy: a database with a registered engine refuses it, a freed entry keeps its slot (src/gd_template.jl ld_table = :streams)" begin
    # UNVERIFIED on the kernel: gate decides
    gd = LK.setupProlog(_R)                                       # unbooted: its tables are empty
    ld = LK._bare_local_data(gd)                                  # not `PL_local_data{_R}(gd)`: since S2a3 that runs initIO, whose three process streams the copy refuses by themselves
    i = LK.registerLocalData!(gd.ld_table, ld)
    @test_throws ErrorException LK.copy_global_data(gd)           # a wrapped stream is open
    LK.unregisterLocalData!(gd.ld_table, i)
    c = LK.copy_global_data(gd)
    @test length(c.ld_table) == 1 && c.ld_table[1] === nothing    # same shape, empty
    @test c.ld_table !== gd.ld_table
    @test typeof(c.ld_table) == typeof(gd.ld_table)
end

@testset "the pins are all used, none vacuous: one extractor, both sides non-empty" begin
    ids = [c[1] for c in _TW_CASES]
    pinids = String[first(split(l, " ")) for l in _TW_PINNED]
    @test length(unique(ids)) == length(ids)
    @test pinids == ids                                           # a pin for every case, in the order of the cases
    @test sort!(collect(keys(_TW_GOT))) == sort(ids)              # every pin was compared with a kernel transcript
    @test all(!isempty, values(_TW_GOT))
    pins = [String(last(split(l, " "; limit=2))) for l in _TW_PINNED]
    @test all(!isempty, pins)
    # the extractor tells the outputs apart (it can fail): a lost prompt, a lost event line, a changed code
    @test _tw_enc("|: <97>\n") != _tw_enc("<97>\n")
    @test _tw_enc("<97>\n<98>\n") != _tw_enc("<97>\n")
    @test _tw_enc("<97>\n") != _tw_enc("<98>\n")
    @test _tw_enc("a\\n") != _tw_enc("a\n")                      # a backslash-n is not a newline
    @test count(p -> occursin("|: ", p), pins) >= 8                                 # most cases show a prompt ...
    @test count(p -> !occursin("|: ", p), pins) >= 4                                # ... and some show none (the guard can fail the other way)
    @test occursin("|: <-1>", _tw_pin("e03"))                                       # the end-of-file fill prompts
    @test !startswith(_tw_pin("e16"), "|: ")                                        # bom(true) lost the first prompt
end
